  const ls_get = (k) => { try { return localStorage.getItem(k); } catch (e) { return null; } };
  const ls_set = (k, v) => { try { localStorage.setItem(k, v); } catch (e) {} };
  const reduced = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  document.documentElement.classList.add("v53");

  const byId = new Map(F.b.map((b) => [b.id, b]));
  const byLi = new Map(F.b.filter((b) => b.li >= 0).map((b) => [b.li, b]));
  const nov = () => typeof RLIST === "undefined" || RLIST === "nov";
  const PHASES = [["construction", "Construction"], ["procurement", "Procurement"], ["design", "Design"], ["proposed", "Proposed"]];
  const KIND = { new: "New building", rebuild: "Rebuild", systems: "Systems work", demolition: "Demolition", other: "Other" };
  const FSTAT = { open: "open (not on Parks' closed list)", closed: "closed", "rooms closed": "rooms closed, building not on the closed list" };
  const dname = (id) => (DATA.d[id] ? DATA.d[id].name.split(" · ")[0] : "");
  const fmtDate = (s) => { if (!s) return ""; const d = new Date(s + "T12:00:00"); return isNaN(d) ? s : d.toLocaleDateString("en-US", { month: "short", year: "numeric" }); };

  // Phase picker for Projected work and the 2030 scenario. Every phase the FOIL records is ticked by default.
  const PW = { ph: { construction: true, procurement: true, design: true, proposed: true }, lay: true };
  try { const s = JSON.parse(ls_get("v53-phases") || "null"); if (s) Object.assign(PW.ph, s); } catch (e) {}
  PW.lay = ls_get("v53-parkslayer") !== "0";
  const phOn = (p) => !!PW.ph[p.ph];

  // District of each FOIL building and project (the one it sits in, or the nearest), worked out once.
  let homed = false;
  const home = () => { if (homed) return; homed = true; F.b.forEach((b) => (b.cd = homeOf(b.lon, b.lat)[0])); F.p.forEach((p) => (p.cd = homeOf(p.lon, p.lat)[0])); };

  // FOIL buildings and projects near one district pack, in its coordinates (the same margin as planned sites).
  const near = new WeakMap();
  function foilIn(K) {
    if (near.has(K)) return near.get(K);
    const Kp = prep(K), inB = (x, y) => x > Kp._B[0] - 300 && x < Kp._B[2] + 300 && y > Kp._B[1] - 300 && y < Kp._B[3] + 300;
    const put = (o) => { const [x, y] = toXY(Kp, o.lon, o.lat); return { o, x, y }; };
    const v = { b: F.b.map(put).filter((q) => inB(q.x, q.y)), p: F.p.map(put).filter((q) => inB(q.x, q.y)) };
    near.set(K, v);
    return v;
  }
  window.V53 = { F, foilIn, PW };

  /* ---------- 3a. the 2030 scenario: Appendix A sites, plus Parks projects in the ticked phases ---------- */
  function parksAdds(K) {
    const add = [], reopen = [];
    foilIn(K).p.forEach((q, i) => {
      if (!phOn(q.o)) return;
      if (q.o.k === "new") add.push({ x: q.x, y: q.y, n: q.o.t, _k: "pw" + i });
      else if (q.o.k === "rebuild" && q.o.tli >= 0 && nov()) {
        const r = K.rest.find((x) => x.li === q.o.tli);
        if (r && !r.ok) reopen.push({ x: r.x, y: r.y, n: r.n, _k: "pr" + i });
      }
    });
    return { add, reopen };
  }
  function pointsFor(K, appendix, parks) {
    const R = counted(K, st, []);
    if (appendix) pipeIn(K).forEach((o, i) => { if (PIPE_BUILT.test(o.q[5])) R.push({ x: o.x, y: o.y, n: o.q[2], _k: "pp" + i }); });
    if (parks) { const a = parksAdds(K); R.push(...a.add, ...a.reopen); }
    return R;
  }
